"""Auditor's spy (temporary): records every real pytest process a test starts, with its -n and timeout."""
import json
import os
import subprocess

_LOG = os.environ["W267_SPY_LOG"]
_init, _comm, _wait = subprocess.Popen.__init__, subprocess.Popen.communicate, subprocess.Popen.wait


def _is_pytest(argv):
    return "pytest" in argv or (argv and os.path.basename(argv[0]) in ("pytest", "py.test"))


def _record(kind, argv, **data):
    data.update(kind=kind, argv=argv, test=os.environ.get("PYTEST_CURRENT_TEST", ""), pid=os.getpid())
    with open(_LOG, "a", encoding="utf-8") as f:
        f.write(json.dumps(data) + "\n")


def init(self, args, *a, **k):
    _init(self, args, *a, **k)
    argv = [str(x) for x in args] if isinstance(args, (list, tuple)) else [str(args)]
    self._w267 = argv
    if _is_pytest(argv):
        _record("popen", argv, env_tmpdir=(k.get("env") or {}).get("TMPDIR"))


def communicate(self, *a, **k):
    argv = getattr(self, "_w267", [])
    if _is_pytest(argv):
        _record("communicate", argv, timeout=k.get("timeout", a[1] if len(a) > 1 else None))
    return _comm(self, *a, **k)


def wait(self, *a, **k):
    argv = getattr(self, "_w267", [])
    if _is_pytest(argv) and (k.get("timeout") is not None or a):
        _record("wait", argv, timeout=k.get("timeout", a[0] if a else None))
    return _wait(self, *a, **k)


subprocess.Popen.__init__, subprocess.Popen.communicate, subprocess.Popen.wait = init, communicate, wait
EOF
